function moldSpread(grid) {
  let state = grid.map((row) => [...row]);
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  for (let minute = 0; ; minute++) {
    if (!state.some((row) => row.includes('F'))) return minute;
    let changed = false;
    const next = state.map((row, r) => row.map((cell, c) => {
      if (cell === 'F' && dirs.some(([dr, dc]) => state[r + dr] && state[r + dr][c + dc] === 'S')) { changed = true; return 'S'; }
      return cell;
    }));
    if (!changed) return -1;
    state = next;
  }
}

function moldSpread(grid) {
  const rows = grid.length, cols = grid[0].length;
  const state = grid.map((row) => [...row]);
  let queue = [], fresh = 0;
  for (let r = 0; r < rows; r++)
    for (let c = 0; c < cols; c++) {
      if (state[r][c] === 'S') queue.push([r, c]);
      else if (state[r][c] === 'F') fresh++;
    }
  let minutes = 0;
  while (queue.length && fresh) {
    const next = [];
    for (const [r, c] of queue)
      for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nr = r + dr, nc = c + dc;
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && state[nr][nc] === 'F') {
          state[nr][nc] = 'S';
          fresh--;
          next.push([nr, nc]);
        }
      }
    queue = next;
    minutes++;
  }
  return fresh ? -1 : minutes;
}
